import { frameworkTracer } from "./tracer.js";
//#region src/server/app-metadata-tracing.ts
function createAppMetadataModuleRoute(routeSegments, moduleType) {
	return `/${[...routeSegments.filter((segment) => !segment.startsWith("@")), moduleType].join("/")}`;
}
function traceGenerateMetadata(moduleRoute, callback) {
	return frameworkTracer.trace(createGenerateMetadataSpanDescriptor(moduleRoute), callback);
}
function createGenerateMetadataSpanDescriptor(moduleRoute) {
	return {
		attributes: { "next.page": moduleRoute },
		name: `generateMetadata ${moduleRoute}`,
		type: "ResolveMetadata.generateMetadata"
	};
}
//#endregion
export { createAppMetadataModuleRoute, createGenerateMetadataSpanDescriptor, traceGenerateMetadata };
